 import React, { useState, useEffect } from 'react'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import { Link } from 'react-router-dom'

export default function Community() {
    const { user, profile } = useAuth()
    const [communities, setCommunities] = useState([])
    const [myCommunities, setMyCommunities] = useState([])
    const [loading, setLoading] = useState(true)
    const [tab, setTab] = useState('my')
    const [selectedCommunity, setSelectedCommunity] = useState(null)
    const [communityPosts, setCommunityPosts] = useState([])
    const [showPosts, setShowPosts] = useState(false)

    useEffect(() => {
        loadCommunities()
    }, [tab, user])

    const loadCommunities = async () => {
        setLoading(true)
        try {
            // Load all communities
            const { data: allCommunities } = await supabase
                .from('communities')
                .select(`
                    *,
                    profiles:creator_id (id, username, full_name, avatar_url)
                `)
                .order('member_count', { ascending: false })

            setCommunities(allCommunities || [])

            // Load communities user is a member of
            if (user) {
                const { data: memberCommunities } = await supabase
                    .from('community_members')
                    .select(`
                        community_id,
                        communities (*)
                    `)
                    .eq('user_id', user.id)
                    .eq('status', 'active')

                const myCommunityData = memberCommunities?.map(m => m.communities) || []
                setMyCommunities(myCommunityData)
            }
        } catch (error) {
            console.error('Error loading communities:', error)
        } finally {
            setLoading(false)
        }
    }

    const loadCommunityPosts = async (communityId) => {
        try {
            const { data, error } = await supabase
                .from('community_posts')
                .select(`
                    *,
                    profiles:user_id (id, username, full_name, avatar_url)
                `)
                .eq('community_id', communityId)
                .order('created_at', { ascending: false })

            if (error) throw error
            setCommunityPosts(data || [])
            setShowPosts(true)
        } catch (error) {
            console.error('Error loading community posts:', error)
        }
    }

    const renderCommunityCard = (community) => {
        const isMember = myCommunities.some(c => c.id === community.id)
        const isCreator = user?.id === community.creator_id

        return (
            <div key={community.id} className="bg-white rounded-xl shadow-md p-4 hover:shadow-lg transition">
                <div className="flex items-start justify-between">
                    <div className="flex-1">
                        <div className="flex items-center gap-2">
                            <span className="text-2xl">🏛️</span>
                            <h3 className="font-bold text-gray-800">{community.name}</h3>
                        </div>
                        <p className="text-sm text-gray-500 mt-1 line-clamp-2">
                            {community.description || 'A private community for football predictions'}
                        </p>
                        <div className="flex items-center gap-4 mt-3 text-sm text-gray-400">
                            <span>👥 {community.member_count || 0} members</span>
                            <span>📝 {community.post_count || 0} posts</span>
                            <span>💰 R50/month</span>
                        </div>
                    </div>
                    <div className="ml-4 flex flex-col items-end gap-2">
                        {isCreator ? (
                            <span className="text-xs bg-yellow-100 text-yellow-800 px-2 py-1 rounded-full">Admin</span>
                        ) : isMember ? (
                            <span className="text-xs bg-green-100 text-green-800 px-2 py-1 rounded-full">Member</span>
                        ) : (
                            <span className="text-xs bg-gray-100 text-gray-600 px-2 py-1 rounded-full">Join</span>
                        )}
                        <button
                            onClick={() => {
                                setSelectedCommunity(community)
                                loadCommunityPosts(community.id)
                            }}
                            className="text-xs bg-blue-500 text-white px-3 py-1 rounded-lg hover:bg-blue-600 transition"
                        >
                            View Posts
                        </button>
                    </div>
                </div>
            </div>
        )
    }

    return (
        <div>
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-gray-800">🏛️ Communities</h1>
                    <p className="text-gray-500">Join communities, share predictions, and connect with fans</p>
                </div>
                <Link 
                    to="/community/create"
                    className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition font-medium"
                >
                    + Create Community
                </Link>
            </div>

            {/* Tabs */}
            <div className="flex gap-2 mb-6">
                <button
                    onClick={() => setTab('my')}
                    className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                        tab === 'my' 
                            ? 'bg-green-600 text-white' 
                            : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                    }`}
                >
                    📁 My Communities
                </button>
                <button
                    onClick={() => setTab('discover')}
                    className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                        tab === 'discover' 
                            ? 'bg-green-600 text-white' 
                            : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                    }`}
                >
                    🔍 Discover
                </button>
            </div>

            {loading ? (
                <div className="text-center py-12">
                    <div className="text-gray-500">Loading...</div>
                </div>
            ) : (
                <>
                    {tab === 'my' && (
                        <div>
                            {!user ? (
                                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                                    <div className="text-4xl mb-4">🔒</div>
                                    <p className="text-gray-500">Please sign in to see your communities</p>
                                </div>
                            ) : myCommunities.length === 0 ? (
                                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                                    <div className="text-4xl mb-4">🏛️</div>
                                    <p className="text-gray-500">You haven't joined any communities yet</p>
                                    <p className="text-sm text-gray-400">Discover communities and start predicting with friends</p>
                                    <button 
                                        onClick={() => setTab('discover')}
                                        className="mt-4 bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700"
                                    >
                                        Discover Communities
                                    </button>
                                </div>
                            ) : (
                                <div className="space-y-4">
                                    {myCommunities.map(renderCommunityCard)}
                                </div>
                            )}
                        </div>
                    )}

                    {tab === 'discover' && (
                        <div>
                            {communities.length === 0 ? (
                                <div className="text-center py-12 bg-white rounded-xl shadow-md">
                                    <div className="text-4xl mb-4">🔍</div>
                                    <p className="text-gray-500">No communities found</p>
                                    <p className="text-sm text-gray-400">Be the first to create a community!</p>
                                </div>
                            ) : (
                                <div className="space-y-4">
                                    {communities.map(renderCommunityCard)}
                                </div>
                            )}
                        </div>
                    )}
                </>
            )}

            {/* Community Posts Modal */}
            {showPosts && selectedCommunity && (
                <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl max-w-2xl w-full max-h-[80vh] overflow-y-auto p-6">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="text-xl font-bold text-gray-800">
                                📝 Posts in {selectedCommunity.name}
                            </h3>
                            <button 
                                onClick={() => {
                                    setShowPosts(false)
                                    setSelectedCommunity(null)
                                    setCommunityPosts([])
                                }}
                                className="text-gray-400 hover:text-gray-600 text-2xl"
                            >
                                ×
                            </button>
                        </div>

                        {communityPosts.length === 0 ? (
                            <div className="text-center py-8 text-gray-500">
                                No posts yet in this community.
                            </div>
                        ) : (
                            <div className="space-y-4">
                                {communityPosts.map((post) => (
                                    <div key={post.id} className="border border-gray-200 rounded-lg p-4">
                                        <div className="flex items-center gap-3 mb-2">
                                            <div className="w-8 h-8 bg-green-500 rounded-full flex items-center justify-center text-white font-bold text-sm">
                                                {post.profiles?.username?.[0]?.toUpperCase() || 'U'}
                                            </div>
                                            <div>
                                                <div className="font-semibold text-sm">
                                                    {post.profiles?.full_name || post.profiles?.username || 'Unknown'}
                                                </div>
                                                <div className="text-xs text-gray-400">
                                                    {new Date(post.created_at).toLocaleDateString()}
                                                </div>
                                            </div>
                                        </div>
                                        <p className="text-gray-800 text-sm">{post.text}</p>
                                        {post.prediction_data && (
                                            <div className="mt-2 bg-gray-50 rounded-lg p-2 text-sm">
                                                <div className="flex items-center justify-between">
                                                    <span>📊 {post.prediction_data.result || 'Draw'}</span>
                                                    <span>🟨{post.prediction_data.yellowCards || 0} 🟥{post.prediction_data.redCards || 0}</span>
                                                    <span>🏁{post.prediction_data.corners || 0}</span>
                                                </div>
                                            </div>
                                        )}
                                        <div className="mt-2 text-xs text-gray-400">
                                            ❤️ {post.likes_count || 0} likes
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
    )
}
